import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:flutter/material.dart';
import '../services/fusion_marketing_service.dart';

class FusionMarketingApprovalPage extends StatelessWidget {
  const FusionMarketingApprovalPage({super.key});
  @override Widget build(BuildContext context) => Scaffold(appBar: AppBar(title: const Text('핵융합 캠페인 승인')), body: StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream: FirebaseFirestore.instance.collection('marketing_campaigns').where('campaignEngine', isEqualTo: 'FUSION_V1').where('status', isEqualTo: 'pending').snapshots(), builder: (_, s) { if (s.hasError) return Center(child: Text('목록 오류: ${s.error}')); final docs = s.data?.docs ?? []; if (docs.isEmpty) return const Center(child: Text('승인 대기 캠페인이 없습니다.')); return ListView(padding: const EdgeInsets.all(12), children: docs.map((d) { final x=d.data(); return Card(child: Padding(padding: const EdgeInsets.all(14), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text('${x['campaignTitle'] ?? x['campaignName']}', style: const TextStyle(fontSize: 18,fontWeight: FontWeight.bold)), Text(x['campaignType']=='ORQUBE_OFFICIAL' ? 'ORQUBE 공식 홍보' : '토큰 홍보 · ${x['tokenSymbol'] ?? ''}'), const SizedBox(height: 8), Text('${x['nucleus'] ?? ''}'), const SizedBox(height: 10), Wrap(spacing: 8, children: [FilledButton(onPressed: () => _act(context,d.id,'APPROVE'), child: const Text('승인')), OutlinedButton(onPressed: () => _act(context,d.id,'HOLD'), child: const Text('보류')), TextButton(onPressed: () => _act(context,d.id,'REJECT'), child: const Text('반려'))])]))); }).toList()); }));
  Future<void> _act(BuildContext context,String id,String action) async { try { await FusionMarketingService().workflow(campaignId:id,action:action); if(context.mounted) ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('처리되었습니다.'))); } on FusionMarketingException catch(e) { if(context.mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(e.message))); } }
}
